const end=new Date($now.toISO());
  if(!Number.isFinite(end.getTime())) throw new Error('Invalid report time');
  const start=new Date(end.getTime()-7*24*60*60*1000);
  const from=start.toISOString(), until=end.toISOString();
  const week = $now.setZone('Europe/Moscow').startOf('week');
  const weekStart = week.toISODate();
  const previousWeekStart = week.minus({ weeks: 1 }).toISODate();
  const base='repo:Artem037/ITMOv2 is:issue';
  return [{json:{repository:'Artem037/ITMOv2',start:from,end:until,weekStart,previousWeekStart,queries:{
    created:`${base} created:>=${from} created:<${until}`,
    closed:`${base} is:closed closed:>=${from} closed:<${until}`,
    open:`${base} is:open created:>=${from} created:<${until}`,
    updated:`${base} updated:>=${from} updated:<${until}`,
  }}}];

const period=$('Период отчёта').first().json;
  const sources=[['created','Созданы за неделю'],['closed','Закрыты за неделю'],['open','Новые открытые'],['updated','Обновлены за неделю']];
  const zero=()=>({created:0,closed:0,open:0,updated:0});
  const summary=zero();
  const by_type=Object.fromEntries(['bug','task','feature-request','needs-triage','other'].map(t=>[t,zero()]));
  const by_author=Object.create(null);
  for(const [metric,name] of sources){
    const response=$(name).first().json;
    const data=response.body;
    if(response.statusCode!==200||!data||!Array.isArray(data.items)||!Number.isSafeInteger(data.total_count)||data.total_count<0)
      throw new Error(`Некорректный ответ GitHub: ${name}`);
    if(data.total_count>100) throw new Error(`Локальный лимит отчёта: ${name} вернул ${data.total_count} результатов; максимум 100. Уменьшите период или добавьте пагинацию.`);
    if(data.incomplete_results!==false||data.items.length!==data.total_count)
      throw new Error(`Неполные результаты GitHub: ${name}. Письмо не отправлено.`);
    const seen=new Set();
    for(const item of data.items){
      if(item.pull_request) continue;
      if(item.id===undefined||seen.has(item.id)) throw new Error(`Некорректный/повторный Issue в ${name}`);
      seen.add(item.id);
      const labels=(Array.isArray(item.labels)?item.labels:[]).map(l=>typeof l==='string'?l:l.name);
      const type=['bug','task','feature-request','needs-triage'].find(t=>labels.includes(t))||'other';
      const author=typeof item.user?.login==='string'?item.user.login:'unknown';
      by_author[author]??=zero();
      summary[metric]+=1; by_type[type][metric]+=1; by_author[author][metric]+=1;
    }
  }
  const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const columns='<th>Созданы</th><th>Закрыты</th><th>Из новых открыты сейчас</th><th>Обновлены</th>';
  const cells=row=>sources.map(([metric])=>`<td>${escape(row[metric])}</td>`).join('');
  const table=(heading,records)=>`<h2>${escape(heading)}</h2><table border="1" cellpadding="8" cellspacing="0"><thead><tr><th>Группа</th>${columns}</tr></thead><tbody>${records.map(([key,value])=>`<tr><td>${escape(key)}</td>${cells(value)}</tr>`).join('')}</tbody></table>`;
  const authorRows=Object.entries(by_author).sort(([a],[b])=>a.localeCompare(b));
  const empty=Object.values(summary).every(value=>value===0)?'<p>Нет Issues за период.</p>':'';
  const html='<!doctype html><html lang="ru"><head><meta charset="UTF-8"></head><body>'
    +`<h1>Еженедельный отчёт GitHub Issues</h1><p>Репозиторий: ${escape(period.repository)}</p>`
    +`<p>Последние 7 дней: ${escape(period.start)} ≤ время &lt; ${escape(period.end)} (UTC).</p>${empty}`
    +table('Сводка',[['Issues',summary]])+table('По типу (лейблу)',Object.entries(by_type))
    +(authorRows.length?table('По автору',authorRows):'<h2>По автору</h2><p>Нет данных.</p>')
    +'<p>Метрики пересекаются и не складываются в общий итог. «Из новых открыты сейчас» — текущий статус Issues, созданных за период. Pull Requests исключены. Тип other — без классификационных лейблов.</p></body></html>';
  return [{json:{repository:period.repository,period:{start:period.start,end:period.end},summary,by_type,by_author,
    subject:`Issues — ${period.repository} — ${period.start.slice(0,10)} → ${period.end.slice(0,10)}`,html}}];

const report = $('Собрать HTML-отчёт').first().json;
const { weekStart, previousWeekStart } = $('Период отчёта').first().json;
const { period, summary, by_type, by_author } = report;
const snapshot = { period, summary, by_type, by_author };
const metrics = {
  created: 'Созданы',
  closed: 'Закрыты',
  open: 'Из новых открыты сейчас',
  updated: 'Обновлены',
};
const keys = Object.keys(metrics);

let previous = null;
try {
  const stored = JSON.parse($input.first().json.stats_json ?? 'null');
  if (keys.every(key => Number.isSafeInteger(stored?.summary?.[key]) && stored.summary[key] >= 0)) {
    previous = stored;
  }
} catch {
  previous = null;
}

let delta = null;
let comparisonHtml = '<p>Данные прошлой недели (' + previousWeekStart + ') недоступны.</p>';
if (previous) {
  delta = Object.fromEntries(keys.map(key => [key, summary[key] - previous.summary[key]]));
  const signed = value => value === 0 ? '0' : value > 0 ? '+' + value : '−' + Math.abs(value);
  const rows = keys.map(key =>
    '<tr><td>' + metrics[key] + '</td><td>' + previous.summary[key] + '</td><td>' + summary[key]
    + '</td><td>' + signed(delta[key]) + '</td></tr>'
  ).join('');
  comparisonHtml = '<p>Снимки статистики за недели с ' + previousWeekStart + ' и ' + weekStart + '.</p>'
    + (previous.demo === true ? '<p>Для прошлой недели использованы демонстрационные данные.</p>' : '')
    + '<table border="1" cellpadding="8" cellspacing="0"><thead><tr><th>Метрика</th>'
    + '<th>Прошлая неделя</th><th>Текущий отчёт</th><th>Δ</th></tr></thead><tbody>' + rows + '</tbody></table>';
}

const prompt = [
  'Напиши 2–3 коротких предложения по-русски для еженедельного отчёта GitHub Issues. Верни обычный текст без Markdown и заголовка.',
  'Используй только переданные числа. Объясни самые заметные изменения по Δ. Метрики могут пересекаться, их нельзя суммировать. Не придумывай причины изменений.',
  'Если предыдущих данных нет, кратко опиши текущие показатели и укажи, что сравнение недоступно. Если прошлые данные демонстрационные, прямо упомяни это.',
  JSON.stringify({
    metrics, current: { summary, by_type },
    previous: previous ? { summary: previous.summary, demo: previous.demo === true } : null, delta,
  }),
].join('\n');

return [{ json: {
  repository: report.repository, weekStart, statsJson: JSON.stringify(snapshot),
  delta, comparisonHtml, prompt,
} }];

const report = $('Собрать HTML-отчёт').first().json;
const { comparisonHtml } = $('Сравнить недели').first().json;
const { text } = $input.first().json;
const comment = typeof text === "string" ? text.trim() : "";
const entities = { "&": "&amp;", "<": "&lt;", ">": "&gt;", "\"": "&quot;", "'": "&#39;" };
const safeComment = comment
  ? comment.replace(/[&<>"']/g, character => entities[character]).replace(/\r?\n/g, '<br>')
  : 'AI-комментарий недоступен в этом запуске.';
const appendix = '<h2>Сравнение с прошлой неделей</h2>' + comparisonHtml
  + '<h2>AI-комментарий недели</h2><p>' + safeComment + '</p>';
return [{ json: { subject: report.subject, html: report.html.replace('</body>', () => appendix + '</body>') } }];
